const connection = msg.payload;
const clients    = Object.values(connection.clients);
const target     = clients.find(c => c.client_system === "wasos");
const source     = clients.find(c => c.client_system !== "wasos");

msg.topic    = source.client_system;
msg.metadata = {
    source:     source,
    target:     target,
    connection_name: connection.name
};

return msg;

return {
    _msgid: msg._msgid,
    topic: "new_message",
    entry: {
        id:        msg.payload.id,
        text:      msg.payload.text,
        timestamp: msg.payload.timestamp,
        author:    msg.payload.author,
        files:     msg.payload.files,
        labels:    msg.payload.labels,
        metadata:  msg.metadata
    }
};

const text = msg.payload.text;
if (!text) return msg;

const regex = /Posisjonen til delhendelsen '(.+?)' ble endret til '([0-9.]+):([0-9.]+)' \(var: '(.+?):(.+?)'\)/;
const match = text.match(regex);

if (match) {
    const name = match[1];
    const lng = parseFloat(match[2]);
    const lat = parseFloat(match[3]);

    const connection_name = msg.metadata.connection_name;
    const key = `parat_bridge.connections.${connection_name}.delhendelse_positions`;
    const positions = global.get(key) || [];

    const existingIndex = positions.findIndex(p => p.name === name);
    if (existingIndex >= 0) {
        positions[existingIndex].lat = lat;
        positions[existingIndex].lng = lng;
    } else {
        positions.push({ name, lat, lng });
    }

    global.set(key, positions);
}

return msg;

const files = msg.payload.files
    || (msg.payload.entry && msg.payload.entry.files)
    || [];
if (files.length === 0) return msg;

const connection_name = msg.metadata.connection_name;
const key = `parat_bridge.connections.${connection_name}.delhendelse_positions`;
const positions = global.get(key) || [];
if (positions.length === 0) return msg;

const mapCaptureRegex = /Map_Capture-.+?\(([0-9.]+),([0-9.]+)\)\.png/;

for (const file of files) {
    if (!file.name) continue;
    const match = file.name.match(mapCaptureRegex);
    if (!match) continue;

    const fileLat = parseFloat(match[1]);
    const fileLng = parseFloat(match[2]);

    // Compare against stored positions (round to 6 decimals)
    const verified = positions.find(p =>
        p.lat.toFixed(6) === fileLat.toFixed(6) &&
        p.lng.toFixed(6) === fileLng.toFixed(6)
    );

    if (verified) {
        msg.metadata.geo = {
            lat: verified.lat,
            lng: verified.lng,
            name: verified.name
        };
        node.warn(`Geo match: "${verified.name}" at ${verified.lat},${verified.lng}`);
        break;
    }
}

return msg;
